package com.requestmanagement.backend.guesttracking;

import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.*;
import java.util.regex.*;
import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc
class GuestTrackingIntegrationTests {
 @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc; @MockitoBean JavaMailSender mailSender;
 private static final String PREFIX="Phase13-";
 @BeforeEach void resetMail(){reset(mailSender);}
 @AfterEach void cleanup(){jdbc.update("DELETE FROM guest_tracking_sessions WHERE request_id IN (SELECT request_id FROM requests WHERE title LIKE ?)",PREFIX+"%");jdbc.update("DELETE FROM guest_tracking_challenges WHERE request_id IN (SELECT request_id FROM requests WHERE title LIKE ?) OR request_id IS NULL",PREFIX+"%");jdbc.update("DELETE FROM guest_communications WHERE request_id IN (SELECT request_id FROM requests WHERE title LIKE ?)",PREFIX+"%");jdbc.update("DELETE FROM requests WHERE title LIKE ?",PREFIX+"%");jdbc.update("DELETE FROM project_guest_form_settings WHERE project_id IN (SELECT project_id FROM projects WHERE project_name LIKE ?)",PREFIX+"%");jdbc.update("DELETE FROM project_status_columns WHERE project_id IN (SELECT project_id FROM projects WHERE project_name LIKE ?)",PREFIX+"%");jdbc.update("DELETE FROM project_work_types WHERE project_id IN (SELECT project_id FROM projects WHERE project_name LIKE ?)",PREFIX+"%");jdbc.update("DELETE FROM projects WHERE project_name LIKE ?",PREFIX+"%");}

 @Test void matchingAndNonMatchingRequestsReturnSamePublicMessage() throws Exception {long request=fixture();Cookie csrf=csrf();String valid=requestCode(request,"phase13@example.com",csrf).getResponse().getContentAsString();String invalid=requestCode(99999999,"nobody@example.com",csrf).getResponse().getContentAsString();assertThat(valid).contains("If the provided details match a request");assertThat(invalid).contains("If the provided details match a request");verify(mailSender,times(1)).send(any(SimpleMailMessage.class));}

 @Test void verifiedSessionReadsOnlyApprovedDataAndSupportsGuestReply() throws Exception {long request=fixture();Session verified=verifiedSession(request);clearInvocations(mailSender);mvc.perform(get("/api/guest/tracking/request").cookie(verified.sessionCookie())).andExpect(status().isOk()).andExpect(jsonPath("$.trackingNumber").value(String.valueOf(request))).andExpect(jsonPath("$.statusName").value("New")).andExpect(jsonPath("$.assignedToId").doesNotExist()).andExpect(jsonPath("$.comments").doesNotExist()).andExpect(jsonPath("$.timeline").doesNotExist());mvc.perform(post("/api/guest/tracking/communications").cookie(verified.sessionCookie(),verified.csrf()).header("X-XSRF-TOKEN",verified.csrf().getValue()).contentType("application/json").content("{\"message\":\"Guest reply\"}" )).andExpect(status().isCreated()).andExpect(jsonPath("$.senderType").value("GUEST"));assertThat(jdbc.queryForObject("SELECT sender_type FROM guest_communications WHERE request_id=?",String.class,request)).isEqualTo("GUEST");verifyNoInteractions(mailSender);}

 @Test void codeIsSingleUseAndMutationRequiresCsrf() throws Exception {long request=fixture();Cookie csrf=csrf();requestCode(request,"phase13@example.com",csrf);SimpleMailMessage mail=captureMail();String challenge=latestChallenge(request);String code=code(mail);MvcResult verified=verifyCode(challenge,code,csrf).andExpect(status().isNoContent()).andReturn();verifyCode(challenge,code,csrf).andExpect(status().isUnauthorized());Cookie session=verified.getResponse().getCookie(GuestTrackingService.COOKIE);mvc.perform(post("/api/guest/tracking/communications").cookie(session).contentType("application/json").content("{\"message\":\"No csrf\"}" )).andExpect(status().isForbidden());}

 @Test void archivedProjectAllowsReadButBlocksReply() throws Exception {long request=fixture();Session verified=verifiedSession(request);jdbc.update("UPDATE projects SET status='ARCHIVED' WHERE project_id=(SELECT project_id FROM requests WHERE request_id=?)",request);mvc.perform(get("/api/guest/tracking/request").cookie(verified.sessionCookie())).andExpect(status().isOk()).andExpect(jsonPath("$.communicationWritable").value(false));mvc.perform(post("/api/guest/tracking/communications").cookie(verified.sessionCookie(),verified.csrf()).header("X-XSRF-TOKEN",verified.csrf().getValue()).contentType("application/json").content("{\"message\":\"Blocked\"}" )).andExpect(status().isConflict());}

 @Test void fiveFailuresExhaustChallengeEvenWhenCorrectCodeIsLaterUsed() throws Exception {long request=fixture();Cookie csrf=csrf();requestCode(request,"phase13@example.com",csrf);String correct=code(captureMail()),challenge=latestChallenge(request);for(int i=0;i<5;i++)verifyCode(challenge,"000000".equals(correct)?"111111":"000000",csrf).andExpect(status().isUnauthorized());verifyCode(challenge,correct,csrf).andExpect(status().isUnauthorized());assertThat(jdbc.queryForObject("SELECT failed_attempts FROM guest_tracking_challenges WHERE challenge_id=?::uuid",Integer.class,challenge)).isEqualTo(5);}

 @Test void resendInvalidatesOldCodeAndIssuesFreshCode() throws Exception {long request=fixture();Cookie csrf=csrf();requestCode(request,"phase13@example.com",csrf);String oldCode=code(captureMail()),challenge=latestChallenge(request);jdbc.update("UPDATE guest_tracking_challenges SET last_sent_at=last_sent_at-INTERVAL '61 seconds' WHERE challenge_id=?::uuid",challenge);clearInvocations(mailSender);mvc.perform(post("/api/guest/tracking/resend").cookie(csrf).header("X-XSRF-TOKEN",csrf.getValue()).contentType("application/json").content("{\"challengeId\":\""+challenge+"\"}")).andExpect(status().isOk());String freshCode=code(captureMail());verifyCode(challenge,oldCode,csrf).andExpect(status().isUnauthorized());verifyCode(challenge,freshCode,csrf).andExpect(status().isNoContent());}

 @Test void expiredCodeAndImmediateResendAreRejected() throws Exception {long request=fixture();Cookie csrf=csrf();requestCode(request,"phase13@example.com",csrf);String challenge=latestChallenge(request),correct=code(captureMail());mvc.perform(post("/api/guest/tracking/resend").cookie(csrf).header("X-XSRF-TOKEN",csrf.getValue()).contentType("application/json").content("{\"challengeId\":\""+challenge+"\"}")).andExpect(status().isTooManyRequests());jdbc.update("UPDATE guest_tracking_challenges SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE challenge_id=?::uuid",challenge);verifyCode(challenge,correct,csrf).andExpect(status().isUnauthorized());}

 @Test void issuanceLimitAlsoAppliesToGeneralGuestRequests() throws Exception {Cookie csrf=csrf();long general=generalGuestFixture();for(int i=0;i<5;i++)requestCode(general,"phase13@example.com",csrf);mvc.perform(post("/api/guest/tracking/request-code").cookie(csrf).header("X-XSRF-TOKEN",csrf.getValue()).contentType("application/json").content("{\"trackingNumber\":\""+general+"\",\"email\":\"phase13@example.com\"}")).andExpect(status().isTooManyRequests());verify(mailSender,times(5)).send(any(SimpleMailMessage.class));}

 @Test void verifiedGeneralSessionIsRequestScopedAndSupportsTwoWayCommunication() throws Exception {long general=generalGuestFixture();long other=generalGuestFixture();Session verified=verifiedSession(general);mvc.perform(get("/api/guest/tracking/request").cookie(verified.sessionCookie())).andExpect(status().isOk()).andExpect(jsonPath("$.trackingNumber").value(String.valueOf(general))).andExpect(jsonPath("$.projectRequest").value(false)).andExpect(jsonPath("$.requestTypeName").isNotEmpty()).andExpect(jsonPath("$.workTypeName").doesNotExist()).andExpect(jsonPath("$.answers").isEmpty()).andExpect(jsonPath("$.assignedToId").doesNotExist()).andExpect(jsonPath("$.comments").doesNotExist()).andExpect(jsonPath("$.timeline").doesNotExist()).andExpect(jsonPath("$.communicationWritable").value(true));mvc.perform(post("/api/guest/tracking/communications").cookie(verified.sessionCookie(),verified.csrf()).header("X-XSRF-TOKEN",verified.csrf().getValue()).contentType("application/json").content("{\"message\":\"General Guest reply\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.senderType").value("GUEST"));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM guest_communications WHERE request_id=?",Long.class,general)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM guest_communications WHERE request_id=?",Long.class,other)).isZero();}

 @Test void projectAndGeneralSessionsRemainBoundToTheirVerifiedRequest() throws Exception {long project=fixture(),general=generalGuestFixture();Session projectSession=verifiedSession(project);Session generalSession=verifiedSession(general);mvc.perform(get("/api/guest/tracking/request").cookie(projectSession.sessionCookie())).andExpect(status().isOk()).andExpect(jsonPath("$.trackingNumber").value(String.valueOf(project))).andExpect(jsonPath("$.projectRequest").value(true));mvc.perform(get("/api/guest/tracking/request").cookie(generalSession.sessionCookie())).andExpect(status().isOk()).andExpect(jsonPath("$.trackingNumber").value(String.valueOf(general))).andExpect(jsonPath("$.projectRequest").value(false));}

 @Test void passiveReadsDoNotRefreshInactivityAndExpiredSessionCannotRead() throws Exception {long request=fixture();Session verified=verifiedSession(request);String digest=jdbc.queryForObject("SELECT token_digest FROM guest_tracking_sessions WHERE request_id=? ORDER BY created_at DESC LIMIT 1",String.class,request);jdbc.update("UPDATE guest_tracking_sessions SET expires_at=CURRENT_TIMESTAMP+INTERVAL '1 minute' WHERE token_digest=?",digest);mvc.perform(get("/api/guest/tracking/request").cookie(verified.sessionCookie())).andExpect(status().isOk());mvc.perform(get("/api/guest/tracking/communications").cookie(verified.sessionCookie())).andExpect(status().isOk());assertThat(jdbc.queryForObject("SELECT expires_at<CURRENT_TIMESTAMP+INTERVAL '2 minutes' FROM guest_tracking_sessions WHERE token_digest=?",Boolean.class,digest)).isTrue();jdbc.update("UPDATE guest_tracking_sessions SET last_activity_at=CURRENT_TIMESTAMP-INTERVAL '31 minutes',expires_at=CURRENT_TIMESTAMP-INTERVAL '1 minute' WHERE token_digest=?",digest);mvc.perform(get("/api/guest/tracking/request").cookie(verified.sessionCookie())).andExpect(status().isUnauthorized());mvc.perform(get("/api/guest/tracking/communications").cookie(verified.sessionCookie())).andExpect(status().isUnauthorized());}

 @Test void successfulGuestMessageRefreshesActivityButExpiredMessageIsRejectedWithoutPersistence() throws Exception {long request=fixture();Session verified=verifiedSession(request);String digest=jdbc.queryForObject("SELECT token_digest FROM guest_tracking_sessions WHERE request_id=? ORDER BY created_at DESC LIMIT 1",String.class,request);jdbc.update("UPDATE guest_tracking_sessions SET expires_at=CURRENT_TIMESTAMP+INTERVAL '1 minute' WHERE token_digest=?",digest);mvc.perform(post("/api/guest/tracking/communications").cookie(verified.sessionCookie(),verified.csrf()).header("X-XSRF-TOKEN",verified.csrf().getValue()).contentType("application/json").content("{\"message\":\"Meaningful activity\"}" )).andExpect(status().isCreated());assertThat(jdbc.queryForObject("SELECT expires_at>CURRENT_TIMESTAMP+INTERVAL '20 minutes' FROM guest_tracking_sessions WHERE token_digest=?",Boolean.class,digest)).isTrue();long before=jdbc.queryForObject("SELECT COUNT(*) FROM guest_communications WHERE request_id=?",Long.class,request);jdbc.update("UPDATE guest_tracking_sessions SET last_activity_at=CURRENT_TIMESTAMP-INTERVAL '31 minutes',expires_at=CURRENT_TIMESTAMP-INTERVAL '1 minute' WHERE token_digest=?",digest);mvc.perform(post("/api/guest/tracking/communications").cookie(verified.sessionCookie(),verified.csrf()).header("X-XSRF-TOKEN",verified.csrf().getValue()).contentType("application/json").content("{\"message\":\"Must not persist\"}" )).andExpect(status().isUnauthorized());assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM guest_communications WHERE request_id=?",Long.class,request)).isEqualTo(before);}

 @Test void guestSessionCanBeExplicitlyRevoked() throws Exception {long request=fixture();Session verified=verifiedSession(request);mvc.perform(post("/api/guest/tracking/logout").cookie(verified.sessionCookie(),verified.csrf()).header("X-XSRF-TOKEN",verified.csrf().getValue())).andExpect(status().isNoContent());mvc.perform(get("/api/guest/tracking/request").cookie(verified.sessionCookie())).andExpect(status().isUnauthorized());}

 @Test void protectedTrackingDataRequiresVerifiedSession() throws Exception {mvc.perform(get("/api/guest/tracking/request")).andExpect(status().isUnauthorized());mvc.perform(get("/api/guest/tracking/communications")).andExpect(status().isUnauthorized());}

 private Session verifiedSession(long request) throws Exception{Cookie csrf=csrf();requestCode(request,"phase13@example.com",csrf);SimpleMailMessage mail=captureMail();String challenge=latestChallenge(request);MvcResult result=verifyCode(challenge,code(mail),csrf).andExpect(status().isNoContent()).andReturn();return new Session(result.getResponse().getCookie(GuestTrackingService.COOKIE),csrf);}
 private ResultActions verifyCode(String challenge,String code,Cookie csrf)throws Exception{return mvc.perform(post("/api/guest/tracking/verify").cookie(csrf).header("X-XSRF-TOKEN",csrf.getValue()).contentType("application/json").content("{\"challengeId\":\""+challenge+"\",\"code\":\""+code+"\"}"));}
 private MvcResult requestCode(long request,String email,Cookie csrf)throws Exception{return mvc.perform(post("/api/guest/tracking/request-code").cookie(csrf).header("X-XSRF-TOKEN",csrf.getValue()).contentType("application/json").content("{\"trackingNumber\":\""+request+"\",\"email\":\""+email+"\"}")).andExpect(status().isOk()).andReturn();}
 private Cookie csrf()throws Exception{return mvc.perform(get("/api/auth/csrf")).andReturn().getResponse().getCookie("XSRF-TOKEN");}
 private SimpleMailMessage captureMail(){var c=org.mockito.ArgumentCaptor.forClass(SimpleMailMessage.class);verify(mailSender,atLeastOnce()).send(c.capture());return c.getValue();}
 private String code(SimpleMailMessage mail){assertThat(mail.getText()).contains("expires in 10 minutes").contains("You can track your request through the Masar website using your tracking number and registered email.").doesNotContain("localhost","http://","https://","/track-request");Matcher m=Pattern.compile("code is (\\d{6})").matcher(mail.getText());assertThat(m.find()).isTrue();return m.group(1);}
 private String latestChallenge(long request){return jdbc.queryForObject("SELECT challenge_id::text FROM guest_tracking_challenges WHERE request_id=? ORDER BY created_at DESC LIMIT 1",String.class,request);}
 private long fixture(){long p=jdbc.queryForObject("INSERT INTO projects(project_name,status) VALUES (?,'ACTIVE') RETURNING project_id",Long.class,PREFIX+System.nanoTime());Long wt=jdbc.queryForObject("INSERT INTO project_work_types(project_id,work_type_name) VALUES (?,'Task') RETURNING work_type_id",Long.class,p);Long st=jdbc.queryForObject("SELECT status_id FROM project_status_columns WHERE project_id=? AND semantic_key='NEW'",Long.class,p);return jdbc.queryForObject("INSERT INTO requests(title,description,project_work_type_id,priority,project_status_id,guest_name,guest_email,project_id) VALUES (?,'Guest description',?,'MEDIUM',?,'Phase Guest','phase13@example.com',?) RETURNING request_id",Long.class,PREFIX+System.nanoTime(),wt,st,p);}
 private long generalGuestFixture(){Long type=jdbc.queryForObject("SELECT type_id FROM request_types WHERE is_active=true ORDER BY type_id LIMIT 1",Long.class);return jdbc.queryForObject("INSERT INTO requests(title,description,type_id,priority,status,guest_name,guest_email) VALUES (?,'General Guest description',?,'MEDIUM','NEW','Phase Guest','phase13@example.com') RETURNING request_id",Long.class,PREFIX+System.nanoTime(),type);}
 private record Session(Cookie sessionCookie,Cookie csrf){}
}
